    },
    "conflict_c6f637b49ed3be3205dd4106": {
      "classification": "different_products_origins_or_programs",
      "reason": "Claim 1 specifies seamless steel mechanical pipe with WT 0.250-1.50 inches and OD 2.375-14.0 inches, while Claim 2 specifies seamless mechanical pipe with different dimensions (WT 0.118-0.75 inches, OD 1.50-9.625 inches) and additional API specifications.",
      "requires_current_authority_verification": false
    },
    "conflict_23695132344c2386193677bd": {
      "classification": "different_dates_or_policy_stages",
      "reason": "Claim 1 refers to a past event in 2025 where tariffs caused volume reductions, while Claim 2 refers to a future or current expectation of a new record despite tariff uncertainty; they describe different temporal stages.",
      "requires_current_authority_verification": false
    },
    "conflict_f7190367155db1df2dc98059": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 describes cost-cutting measures taken by suppliers, while Claim 2 notes that negotiation results vary and some can pass costs on; these represent different outcomes or strategies within the same context of cost increases.",
