    },
    "conflict_e9f7e250d9bbc45d6f3dc2dd": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 states that only 40% of makers could raise prices to offset costs, while Claim 2 specifies the tariff rate (15%) causing those costs; the low pass-through rate is consistent with the existence of a specific tariff increase.",
      "requires_current_authority_verification": false
    },
    "conflict_9a5abfed8c9da1940ddee172": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 states Hyundai is exploring expansion to 800,000 units, while Claim 2 provides specific details from a CEO interview regarding the review of capacity increases from 500,000 to between 700,000 and 800,000; they are consistent statements.",
      "requires_current_authority_verification": false
    }
  }
}
